def task(l,title,phase,t,items,do,*,key='',look='',iff='',say='',check=True,clock=None,sub='',**kw):
    s=l.slide(title,phase,t,do,sub=sub,check=check,key=key,look=look or (('Check at least five learners’ responses for: '+'; '.join(items)) if check else ''),iff=iff or ('Ask: Which part have you completed? Point to the relevant evidence or instruction, then add the missing step.' if check else ''),say=say or ('Read each instruction, then ask learners to explain their reasoning.' if check else ''),**kw)
    steps(s,items,w=10,dy=.92,size=25,c=COL.get(phase,'47C6E4'))
    if clock:timer(s,clock,'work')
    return s

